                    GetTagResource().CreateOrUpdate(WaitUntil.Completed, originalTags.Value.Data, cancellationToken);
                    RequestContext context = new RequestContext
                    {
                        CancellationToken = cancellationToken
                    };
                    HttpMessage message = _postgresInstancesRestClient.CreateGetRequest(Id.SubscriptionId, Id.ResourceGroupName, Id.Name, context);
                    Response result = Pipeline.ProcessMessage(message, context);
                    Response<PostgresInstanceData> response = Response.FromValue(PostgresInstanceData.FromResponse(result), result);
                    return Response.FromValue(new PostgresInstanceResource(Client, response.Value), response.GetRawResponse());
                }
                else
                {
                    PostgresInstanceData current = Get(cancellationToken: cancellationToken).Value.Data;
                    PostgresInstancePatch patch = new PostgresInstancePatch();
                    foreach (KeyValuePair<string, string> tag in current.Tags)
                    {
                        patch.Tags.Add(tag);
                    }
                    patch.Tags.Remove(key);
                    Response<PostgresInstanceResource> result = Update(patch, cancellationToken: cancellationToken);
                    return Response.FromValue(result.Value, result.GetRawResponse());
                }
            }
            catch (Exception e)
            {
                scope.Failed(e);
                throw;
            }
        }
    }
}
